CREATE OR REPLACE TABLE M360MART.BRONZE.dim_memberProfile (
    member_id                          VARCHAR(20) NOT NULL COMMENT 'Payer-assigned member identifier (MBR-########). Generated by common.identity, which guarantees uniqueness - a truncated hash alone collides at this population size and Snowflake does not enforce the PK.',
