    date_of_birth                      DATE NOT NULL COMMENT 'Date of birth (date-anchor shifted)',
    age_years                          NUMBER(5,0) NOT NULL COMMENT 'Age in whole years as of the pipeline reference date',
    date_of_death                      DATE COMMENT 'Date of death when deceased',
    deceased_flag                      BOOLEAN NOT NULL COMMENT 'True when a date of death is present',
    gender                             VARCHAR(2) NOT NULL COMMENT 'Administrative gender',
