    city                               VARCHAR(100) COMMENT 'City',
    county                             VARCHAR(100) COMMENT 'County',
    state                              VARCHAR(2) COMMENT 'State - drives state-specific PA turnaround rules',
    zip_code                           VARCHAR(10) COMMENT 'Postal code',
    latitude                           NUMBER(11,7) COMMENT 'Latitude. Excluded from SERVING views.',
    longitude                          NUMBER(11,7) COMMENT 'Longitude. Excluded from SERVING views.',
