    CONSTRAINT pk_dim_memberprofile PRIMARY KEY (member_id)
)
COMMENT = 'One row per member (the payer''s own view of the person) | Member demographic master, derived from Synthea patients.csv with all dates shifted by the deterministic date anchor. This is the payer-side identity; ext_patientProfile is the provider-side identity for the same human and the two are reconciled in silver.';

CREATE OR REPLACE TABLE M360MART.BRONZE.dim_memberPlan (
    member_plan_sk                    VARCHAR(40) NOT NULL COMMENT 'Surrogate key for the member-plan span',
    member_id                         VARCHAR(20) NOT NULL COMMENT 'Member this coverage belongs to',
