    pcp_npi                           VARCHAR(10) COMMENT 'Assigned primary care provider NPI',
    pcp_name                          VARCHAR(300) COMMENT 'Assigned primary care provider name',
    pharmacy_carveout_flag            BOOLEAN NOT NULL COMMENT 'True when pharmacy benefits are administered by a separate PBM',
    pharmacy_pbm_name                 VARCHAR(120) COMMENT 'PBM name when carved out',
