    regulatory_tat_standard_days      NUMBER(5,0) NOT NULL COMMENT 'Calendar days allowed for a standard PA decision under this LOB',
    regulatory_tat_urgent_hours       NUMBER(5,0) NOT NULL COMMENT 'Hours allowed for an expedited PA decision under this LOB',
    tat_authority                     VARCHAR(200) NOT NULL COMMENT 'Regulation the turnaround limits come from',
    pa_ruleset_id                     VARCHAR(30) NOT NULL COMMENT 'Identifier of the PA-required service list this plan uses',
    source_system                     VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
