CREATE OR REPLACE TABLE M360MART.BRONZE.dim_memberHistory (
    member_history_sk           VARCHAR(40) NOT NULL COMMENT 'Surrogate key',
    member_id                   VARCHAR(20) NOT NULL COMMENT 'Member',
    sequence_number             NUMBER(6,0) NOT NULL COMMENT 'Ordering of events within a member',
    change_type                 VARCHAR(30) NOT NULL COMMENT 'Nature of the change',
    effective_start_date        DATE NOT NULL COMMENT 'Date the change takes effect',
    effective_end_date          DATE COMMENT 'Date the state ended, NULL when still in force',
    processed_date              DATE NOT NULL COMMENT 'Date the change was actually processed - later than effective_start_date on retro actions',
    enrollment_status           VARCHAR(20) NOT NULL COMMENT 'Resulting status',
    changed_attribute           VARCHAR(60) COMMENT 'Attribute that changed',
    prior_value                 VARCHAR(200) COMMENT 'Value before the change',
    new_value                   VARCHAR(200) COMMENT 'Value after the change',
    change_reason_code          VARCHAR(20) COMMENT 'Reason code',
    change_reason_desc          VARCHAR(200) COMMENT 'Reason description',
    plan_id                     VARCHAR(30) COMMENT 'Plan in force after the change',
    retroactive_flag            BOOLEAN NOT NULL COMMENT 'True when processed_date is after effective_start_date',
    retroactive_days            NUMBER(6,0) COMMENT 'How far back the change was applied',
    coverage_gap_days           NUMBER(6,0) COMMENT 'Days of no coverage created immediately before this event',
    creates_coverage_gap_flag   BOOLEAN NOT NULL COMMENT 'True when this event opened a gap',
    source_system               VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc             TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash                 VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_dim_memberhistory PRIMARY KEY (member_history_sk)
)
COMMENT = 'One row per member per enrolment/status change event | Append-only change log for member status. Includes coverage gaps and retroactive terminations, which are a common root cause of PA eligibility denials and therefore something an analyst must be able to see directly.';

