    estimated_allowed_amt               NUMBER(12,2) COMMENT 'Benchmark allowed amount for the requested service',
    high_cost_review_flag               BOOLEAN NOT NULL COMMENT 'True when the estimated amount crosses the additional-review threshold',
    criteria_ruleset_id                 VARCHAR(40) COMMENT 'Ruleset used to review this request - joins to slv_pa_criteria_ruleset',
    criteria_ruleset_version            VARCHAR(20) COMMENT 'Ruleset version applied',
    pa_status                           VARCHAR(24) NOT NULL COMMENT 'Current case status',
    is_open_flag                        BOOLEAN NOT NULL COMMENT 'True when the case is still open and its SLA clock is running',
    decision_datetime_utc               TIMESTAMP_NTZ COMMENT 'When a final decision was rendered',
    decision_by_role                    VARCHAR(24) COMMENT 'Who decided',
    decision_by_user_id                 VARCHAR(40) COMMENT 'Reviewer identifier',
    denial_reason_code                  VARCHAR(10) COMMENT 'Denial reason',
    denial_reason_desc                  VARCHAR(300) COMMENT 'Specific denial reason - CMS-0057-F requires specificity, not ''does not meet criteria''',
    approved_units                      NUMBER(10,0) COMMENT 'Units approved - less than requested on a partial approval',
    auth_number                         VARCHAR(30) COMMENT 'Authorization number issued on approval. Joins to fct_memberTransactions.related_auth_number.',
    auth_effective_date                 DATE COMMENT 'Authorization valid from',
    auth_expiration_date                DATE COMMENT 'Authorization valid until',
    pend_reason_code                    VARCHAR(10) COMMENT 'Why the case was pended',
    pend_reason_desc                    VARCHAR(300) COMMENT 'Pend reason description',
    pend_letter_sent_date               DATE COMMENT 'Date the request-for-information went out',
    pend_response_received_date         DATE COMMENT 'Date the provider responded',
    clock_paused_days                   NUMBER(6,0) NOT NULL COMMENT 'Days excluded from the regulatory clock while pended',
    auto_adjudicated_flag               BOOLEAN NOT NULL COMMENT 'True when decided without human review',
    auto_adjudication_reason            VARCHAR(200) COMMENT 'Why the rules engine auto-decided, or why it routed to manual review',
    gold_card_exempt_flag               BOOLEAN NOT NULL COMMENT 'True when the provider was PA-exempt for this service at submission',
    regulatory_deadline_datetime_utc    TIMESTAMP_NTZ NOT NULL COMMENT 'Hard decision deadline, computed from LOB, urgency and receipt time',
    tat_elapsed_days                    NUMBER(8,2) COMMENT 'Days elapsed against the clock, excluding pend pauses',
    sla_breach_flag                     BOOLEAN NOT NULL COMMENT 'True when the deadline has already passed',
    letter_of_medical_necessity_flag    BOOLEAN NOT NULL COMMENT 'True when an LMN was submitted',
    attachment_count                    NUMBER(5,0) NOT NULL COMMENT 'Number of clinical attachments',
    clinical_notes_attached_flag        BOOLEAN NOT NULL COMMENT 'True when progress notes were submitted',
    lab_results_attached_flag           BOOLEAN NOT NULL COMMENT 'True when lab results were submitted',
    imaging_attached_flag               BOOLEAN NOT NULL COMMENT 'True when imaging results were submitted',
    appeal_flag                         BOOLEAN NOT NULL COMMENT 'True when the decision was appealed',
    appeal_filed_date                   DATE COMMENT 'Date the appeal was filed',
    appeal_outcome                      VARCHAR(30) COMMENT 'UPHELD, OVERTURNED, PARTIALLY_OVERTURNED or WITHDRAWN',
    appeal_decision_date                DATE COMMENT 'Date the appeal was decided',
    grounded_on_source                  VARCHAR(40) COMMENT 'Which real source record seeded this request (CONDITION, ENCOUNTER, MEDICATION, PROCEDURE)',
    grounded_on_source_id               VARCHAR(80) COMMENT 'Identifier of the seeding source record - makes the grounding auditable',
    source_system                       VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc                     TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash                         VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_fct_memberpa PRIMARY KEY (pa_id)
)
COMMENT = 'One row per prior authorization request | The centrepiece fact. No public dataset contains real PA records, so these are synthesised - but every request is GROUNDED in an actual Synthea condition, encounter or medication for the same member. That grounding is what makes the clinical evidence in ext_* genuinely corroborate or contradict the request, rather than being decorative. A deliberate slice of cases is left open with live SLA clocks.';

CREATE OR REPLACE TABLE M360MART.BRONZE.fct_memberTransactions (
    transaction_id              VARCHAR(40) NOT NULL COMMENT 'Unique transaction identifier',
    claim_id                    VARCHAR(40) COMMENT 'Claim this line belongs to',
    claim_line_number           NUMBER(6,0) COMMENT 'Line number within the claim',
    member_id                   VARCHAR(20) NOT NULL COMMENT 'Member',
    plan_id                     VARCHAR(30) COMMENT 'Plan in force on the service date',
    transaction_type            VARCHAR(30) NOT NULL COMMENT 'Kind of transaction',
    claim_status                VARCHAR(20) COMMENT 'Adjudication outcome',
    service_start_date          DATE COMMENT 'First date of service',
    service_end_date            DATE COMMENT 'Last date of service',
    received_date               DATE COMMENT 'Date the claim was received',
    adjudicated_date            DATE COMMENT 'Date the claim was adjudicated',
    paid_date                   DATE COMMENT 'Date payment was issued',
    billing_provider_npi        VARCHAR(10) COMMENT 'Billing provider NPI',
    rendering_provider_npi      VARCHAR(10) COMMENT 'Rendering provider NPI',
    facility_npi                VARCHAR(10) COMMENT 'Facility NPI',
    provider_network_status     VARCHAR(20) COMMENT 'Network standing',
    place_of_service_code       VARCHAR(4) COMMENT 'Place of service',
    procedure_code              VARCHAR(10) COMMENT 'Procedure code billed',
    procedure_code_system       VARCHAR(12) COMMENT 'Procedure code system',
    procedure_desc              VARCHAR(500) COMMENT 'Procedure description',
    modifier_1                  VARCHAR(4) COMMENT 'First procedure modifier',
    modifier_2                  VARCHAR(4) COMMENT 'Second procedure modifier',
    revenue_code                VARCHAR(6) COMMENT 'Institutional revenue code',
    drg_code                    VARCHAR(10) COMMENT 'Diagnosis-related group, inpatient only',
    units_of_service            NUMBER(10,2) COMMENT 'Units billed',
    primary_dx_icd10            VARCHAR(10) COMMENT 'Primary diagnosis on the line',
    dx_icd10_list               VARIANT COMMENT 'Array of all diagnoses on the claim',
    ndc_code                    VARCHAR(20) COMMENT 'Drug NDC, pharmacy claims only',
    drug_name                   VARCHAR(300) COMMENT 'Drug name, pharmacy claims only',
    quantity_dispensed          NUMBER(12,3) COMMENT 'Quantity dispensed',
    days_supply                 NUMBER(6,0) COMMENT 'Days supply dispensed',
    fill_number                 NUMBER(4,0) COMMENT 'Refill sequence, 0 = original fill',
    is_generic                  BOOLEAN COMMENT 'True for generic dispense',
    formulary_tier              NUMBER(2,0) COMMENT 'Formulary tier at time of fill',
    billed_amt                  NUMBER(14,2) COMMENT 'Provider billed charge',
    allowed_amt                 NUMBER(14,2) COMMENT 'Contractually allowed amount',
    plan_paid_amt               NUMBER(14,2) COMMENT 'Amount the plan paid',
    member_deductible_amt       NUMBER(14,2) COMMENT 'Applied to deductible',
    member_coinsurance_amt      NUMBER(14,2) COMMENT 'Member coinsurance',
    member_copay_amt            NUMBER(14,2) COMMENT 'Member copay',
    member_responsibility_amt   NUMBER(14,2) COMMENT 'Total member responsibility on the line',
    cob_paid_amt                NUMBER(14,2) COMMENT 'Paid by another carrier under COB',
    adjustment_amt              NUMBER(14,2) COMMENT 'Adjustment applied - may be negative',
    outstanding_amt             NUMBER(14,2) COMMENT 'Balance still outstanding',
    related_auth_number         VARCHAR(30) COMMENT 'Authorization that permitted this service, when one existed',
    pa_required_flag            BOOLEAN COMMENT 'True when the service required PA',
    pa_on_file_flag             BOOLEAN COMMENT 'True when a matching authorization was found',
    denial_code                 VARCHAR(20) COMMENT 'Claim denial code',
    denial_desc                 VARCHAR(300) COMMENT 'Claim denial description',
    source_system               VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc             TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash                 VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_fct_membertransactions PRIMARY KEY (transaction_id)
)
COMMENT = 'One row per claim line, payment, adjustment or reversal | Financial and utilisation transaction history. Claim lines carry the diagnosis and procedure detail that silver mines for conservative-care, imaging-prerequisite and step-therapy evidence. related_auth_number links post-service claims back to the authorization that permitted them.';

CREATE OR REPLACE TABLE M360MART.BRONZE.fct_memberEvents (
    event_id             VARCHAR(40) NOT NULL COMMENT 'Unique event identifier',
    member_id            VARCHAR(20) NOT NULL COMMENT 'Member',
    event_datetime_utc   TIMESTAMP_NTZ NOT NULL COMMENT 'When the event occurred',
    event_category       VARCHAR(30) NOT NULL COMMENT 'Kind of interaction',
    event_subtype        VARCHAR(60) COMMENT 'Finer classification',
    channel              VARCHAR(30) NOT NULL COMMENT 'Channel used (PHONE, PORTAL, MAIL, FAX, SMS, EMAIL)',
    direction            VARCHAR(12) NOT NULL COMMENT 'INBOUND or OUTBOUND',
    related_pa_id        VARCHAR(24) COMMENT 'PA case this interaction concerns',
    related_claim_id     VARCHAR(40) COMMENT 'Claim this interaction concerns',
    handled_by_queue     VARCHAR(60) COMMENT 'Servicing queue',
    agent_id             VARCHAR(40) COMMENT 'Handling agent identifier',
    duration_seconds     NUMBER(8,0) COMMENT 'Interaction duration for voice contacts',
    disposition_code     VARCHAR(20) COMMENT 'Outcome code',
    disposition_desc     VARCHAR(300) COMMENT 'Outcome description',
    topic                VARCHAR(80) COMMENT 'What the contact was about',
    resolved_flag        BOOLEAN NOT NULL COMMENT 'True when resolved on this contact',
    escalated_flag       BOOLEAN NOT NULL COMMENT 'True when escalated',
    sentiment_score      NUMBER(4,3) COMMENT 'Synthetic sentiment between -1 and 1',
    notes_text           VARCHAR(2000) COMMENT 'Short interaction note',
    source_system        VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc      TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash          VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_fct_memberevents PRIMARY KEY (event_id)
)
COMMENT = 'One row per member interaction or communication event | Member-facing contact history across all channels. related_pa_id ties correspondence to the PA case it concerns, which is how an analyst sees whether a pend letter actually went out and whether the member or provider responded.';

CREATE OR REPLACE TABLE M360MART.BRONZE.ext_patientProfile (
    ext_patient_id                  VARCHAR(40) NOT NULL COMMENT 'Provider medical record number (MRN-#######)',
    source_org_id                   VARCHAR(30) NOT NULL COMMENT 'Contributing provider organization identifier',
    source_org_name                 VARCHAR(300) NOT NULL COMMENT 'Contributing provider organization name',
    source_ehr_vendor               VARCHAR(40) NOT NULL COMMENT 'EHR platform the data came from',
    data_sharing_agreement_id       VARCHAR(40) NOT NULL COMMENT 'Governing data-sharing agreement',
    vbc_contract_id                 VARCHAR(40) COMMENT 'Value-based-care contract, when attributed',
    payer_member_id                 VARCHAR(20) COMMENT 'Payer member id as asserted by the provider. NULL or wrong on a realistic minority of rows - this is what forces identity resolution.',
    payer_member_id_asserted_flag   BOOLEAN NOT NULL COMMENT 'True when the provider supplied a member id at all',
    match_method                    VARCHAR(20) COMMENT 'How the record was matched to a member',
    match_confidence_score          NUMBER(5,4) COMMENT 'Match confidence between 0 and 1',
    first_name                      VARCHAR(100) COMMENT 'Given name as recorded by the provider',
    last_name                       VARCHAR(100) COMMENT 'Family name as recorded by the provider',
    date_of_birth                   DATE COMMENT 'Date of birth as recorded by the provider',
    gender                          VARCHAR(2) COMMENT 'Gender as recorded by the provider',
    address_line1                   VARCHAR(200) COMMENT 'Street address. Excluded from SERVING views.',
    city                            VARCHAR(100) COMMENT 'City',
    state                           VARCHAR(2) COMMENT 'State',
    zip_code                        VARCHAR(10) COMMENT 'Postal code',
    phone                           VARCHAR(30) COMMENT 'Phone. Excluded from SERVING views.',
    primary_care_provider_npi       VARCHAR(10) COMMENT 'Treating PCP NPI',
    primary_care_provider_name      VARCHAR(300) COMMENT 'Treating PCP name',
    attributed_flag                 BOOLEAN NOT NULL COMMENT 'True when attributed to the VBC contract',
    attribution_start_date          DATE COMMENT 'Attribution period start',
    attribution_end_date            DATE COMMENT 'Attribution period end',
    risk_score_hcc                  NUMBER(6,3) COMMENT 'HCC risk score',
    risk_tier                       VARCHAR(20) COMMENT 'LOW, MODERATE, HIGH or VERY_HIGH',
    last_encounter_date             DATE COMMENT 'Most recent encounter at this organization',
    consent_on_file_flag            BOOLEAN NOT NULL COMMENT 'True when patient consent to share is recorded',
    consent_scope                   VARCHAR(60) COMMENT 'Scope of the recorded consent',
    source_system                   VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc                 TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash                     VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_ext_patientprofile PRIMARY KEY (ext_patient_id)
)
COMMENT = 'One row per patient per contributing provider organization | Provider-side patient identity under a VBC data-sharing agreement. The same human may appear here and in dim_memberProfile under different identifiers; payer_member_id is absent or conflicting for a realistic minority of rows.';

CREATE OR REPLACE TABLE M360MART.BRONZE.ext_patientClinicalRecords (
    clinical_record_id        VARCHAR(40) NOT NULL COMMENT 'Unique clinical record identifier',
    ext_patient_id            VARCHAR(40) NOT NULL COMMENT 'Provider patient identifier',
    payer_member_id           VARCHAR(20) COMMENT 'Payer member id when resolvable',
    source_org_id             VARCHAR(30) NOT NULL COMMENT 'Contributing organization',
    record_type               VARCHAR(30) NOT NULL COMMENT 'Kind of clinical record',
    record_date               DATE NOT NULL COMMENT 'Clinical date of the record',
    recorded_datetime_utc     TIMESTAMP_NTZ COMMENT 'When it was charted',
    encounter_ref             VARCHAR(64) COMMENT 'Encounter this record belongs to',
    source_code               VARCHAR(30) COMMENT 'Native code as recorded in the EHR',
    source_code_system        VARCHAR(12) COMMENT 'Native code system',
    source_code_desc          VARCHAR(500) COMMENT 'Native code description',
    icd10_code                VARCHAR(10) COMMENT 'Crosswalked ICD-10-CM diagnosis code',
    icd10_desc                VARCHAR(500) COMMENT 'Crosswalked ICD-10-CM description',
    cpt_hcpcs_code            VARCHAR(10) COMMENT 'Crosswalked CPT/HCPCS procedure code',
    cpt_hcpcs_desc            VARCHAR(500) COMMENT 'Crosswalked CPT/HCPCS description',
    crosswalk_method          VARCHAR(30) COMMENT 'How the crosswalk was derived (CURATED_MAP, CATEGORY_DEFAULT, UNMAPPED)',
    clinical_status           VARCHAR(20) COMMENT 'ACTIVE, RESOLVED or REMISSION',
    onset_date                DATE COMMENT 'Onset date for conditions',
    resolved_date             DATE COMMENT 'Resolution date for conditions',
    is_chronic_flag           BOOLEAN NOT NULL COMMENT 'True for chronic conditions',
    result_value_numeric      NUMBER(18,6) COMMENT 'Numeric result for labs and vitals',
    result_value_text         VARCHAR(500) COMMENT 'Text result when not numeric',
    result_unit               VARCHAR(40) COMMENT 'Unit of measure',
    reference_range_low       NUMBER(18,6) COMMENT 'Lower bound of the normal range',
    reference_range_high      NUMBER(18,6) COMMENT 'Upper bound of the normal range',
    abnormal_flag             VARCHAR(10) COMMENT 'NORMAL, HIGH, LOW or CRITICAL',
    body_site                 VARCHAR(120) COMMENT 'Anatomical site',
    body_region               VARCHAR(60) COMMENT 'Coarse body region - used to match imaging prerequisites and conservative care to the request',
    laterality                VARCHAR(20) COMMENT 'LEFT, RIGHT, BILATERAL or NA',
    severity                  VARCHAR(20) COMMENT 'MILD, MODERATE or SEVERE',
    performing_provider_npi   VARCHAR(10) COMMENT 'Provider who performed or recorded it',
    source_system             VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc           TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash               VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_ext_patientclinicalrecords PRIMARY KEY (clinical_record_id)
)
COMMENT = 'One row per discrete clinical record (a diagnosis, procedure, lab, vital or imaging result) | Clinical detail from provider EHRs. Source codes are the native SNOMED-CT / LOINC values; the icd10_* and cpt_hcpcs_* columns are the crosswalked equivalents, because PA is transacted on ICD-10 and CPT/HCPCS and an analyst works in those code sets, not SNOMED.';

CREATE OR REPLACE TABLE M360MART.BRONZE.ext_patientEhrEvents (
    ehr_event_id              VARCHAR(40) NOT NULL COMMENT 'Unique event identifier',
    ext_patient_id            VARCHAR(40) NOT NULL COMMENT 'Provider patient identifier',
    payer_member_id           VARCHAR(20) COMMENT 'Payer member id when resolvable',
    source_org_id             VARCHAR(30) NOT NULL COMMENT 'Contributing organization',
    source_ehr_vendor         VARCHAR(40) NOT NULL COMMENT 'EHR platform',
    event_datetime_utc        TIMESTAMP_NTZ NOT NULL COMMENT 'When the event occurred clinically',
    received_datetime_utc     TIMESTAMP_NTZ NOT NULL COMMENT 'When the payer received the message',
    ingestion_latency_hours   NUMBER(8,2) NOT NULL COMMENT 'Hours between occurrence and receipt',
    event_type                VARCHAR(30) NOT NULL COMMENT 'Kind of event',
    adt_message_type          VARCHAR(10) COMMENT 'HL7 ADT message type (A01, A03, A04, A08)',
    encounter_id              VARCHAR(64) COMMENT 'Encounter identifier',
    encounter_class           VARCHAR(20) COMMENT 'Encounter setting',
    encounter_reason_code     VARCHAR(30) COMMENT 'Reason code for the encounter',
    encounter_reason_desc     VARCHAR(500) COMMENT 'Reason description',
    department                VARCHAR(120) COMMENT 'Department or unit',
    location                  VARCHAR(200) COMMENT 'Facility or location name',
    attending_provider_npi    VARCHAR(10) COMMENT 'Attending provider NPI',
    admission_datetime_utc    TIMESTAMP_NTZ COMMENT 'Admission timestamp for inpatient events',
    discharge_datetime_utc    TIMESTAMP_NTZ COMMENT 'Discharge timestamp',
    length_of_stay_days       NUMBER(8,2) COMMENT 'Length of stay in days',
    discharge_disposition     VARCHAR(120) COMMENT 'Where the patient went at discharge',
    order_type                VARCHAR(60) COMMENT 'Order category for order events',
    order_code                VARCHAR(30) COMMENT 'Ordered item code',
    order_desc                VARCHAR(500) COMMENT 'Ordered item description',
    order_status              VARCHAR(30) COMMENT 'PLACED, IN_PROGRESS, COMPLETED or CANCELLED',
    referral_specialty        VARCHAR(150) COMMENT 'Specialty referred to',
    referral_reason           VARCHAR(500) COMMENT 'Reason for referral',
    source_system             VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc           TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash               VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_ext_patientehrevents PRIMARY KEY (ehr_event_id)
)
COMMENT = 'One row per EHR event message | Near-real-time event stream from partner EHRs, modelled on ADT and order messaging. ingestion_latency_hours preserves the fact that these feeds lag, which matters when an analyst asks whether an admission has actually been reported yet.';

CREATE OR REPLACE TABLE M360MART.BRONZE.ext_patientMedicalHistory (
    medical_history_id        VARCHAR(40) NOT NULL COMMENT 'Unique history record identifier',
    ext_patient_id            VARCHAR(40) NOT NULL COMMENT 'Provider patient identifier',
    payer_member_id           VARCHAR(20) COMMENT 'Payer member id when resolvable',
    source_org_id             VARCHAR(30) NOT NULL COMMENT 'Contributing organization',
    history_type              VARCHAR(30) NOT NULL COMMENT 'Kind of history entry',
    onset_date                DATE COMMENT 'Start date',
    end_date                  DATE COMMENT 'End date, NULL when ongoing',
    is_active                 BOOLEAN NOT NULL COMMENT 'True when currently active',
    condition_snomed_code     VARCHAR(30) COMMENT 'SNOMED-CT condition code',
    condition_icd10_code      VARCHAR(10) COMMENT 'Crosswalked ICD-10-CM condition code',
    condition_desc            VARCHAR(500) COMMENT 'Condition description',
    condition_category        VARCHAR(60) COMMENT 'Coarse condition grouping',
    medication_rxnorm_code    VARCHAR(30) COMMENT 'RxNorm concept code',
    medication_ndc_code       VARCHAR(20) COMMENT 'NDC product code',
    medication_name           VARCHAR(300) COMMENT 'Medication as prescribed',
    medication_generic_name   VARCHAR(300) COMMENT 'Generic name',
    therapeutic_class         VARCHAR(120) COMMENT 'Therapeutic class - step therapy is evaluated within a class',
    dose_amount               VARCHAR(60) COMMENT 'Dose amount',
    dose_unit                 VARCHAR(40) COMMENT 'Dose unit',
    route                     VARCHAR(60) COMMENT 'Route of administration',
    frequency                 VARCHAR(60) COMMENT 'Dosing frequency',
    sig_text                  VARCHAR(500) COMMENT 'Prescription directions',
    prescriber_npi            VARCHAR(10) COMMENT 'Prescribing provider NPI',
    prescribed_date           DATE COMMENT 'Date prescribed',
    discontinued_date         DATE COMMENT 'Date discontinued',
    discontinue_reason        VARCHAR(200) COMMENT 'Why it was stopped - ''inadequate response'' is what satisfies a fail-first criterion',
    dispense_count            NUMBER(6,0) COMMENT 'Number of dispenses',
    days_supply_total         NUMBER(8,0) COMMENT 'Cumulative days supply',
    therapy_duration_days     NUMBER(8,0) COMMENT 'Days between first and last dispense - measures trial duration',
    adherence_pdc_pct         NUMBER(5,2) COMMENT 'Proportion of days covered - distinguishes a genuine failed trial from non-adherence',
    is_specialty_drug         BOOLEAN COMMENT 'True for specialty/biologic products',
    requires_pa_flag          BOOLEAN COMMENT 'True when the drug is PA-gated',
    formulary_tier            NUMBER(2,0) COMMENT 'Formulary tier',
    is_first_line_therapy     BOOLEAN COMMENT 'True when this drug is a first-line option in its class',
    allergy_substance         VARCHAR(300) COMMENT 'Allergen',
    allergy_reaction          VARCHAR(300) COMMENT 'Observed reaction',
    allergy_severity          VARCHAR(20) COMMENT 'MILD, MODERATE or SEVERE',
    allergy_criticality       VARCHAR(20) COMMENT 'LOW, HIGH or UNABLE_TO_ASSESS',
    immunization_cvx_code     VARCHAR(10) COMMENT 'CVX vaccine code',
    immunization_desc         VARCHAR(300) COMMENT 'Vaccine description',
    smoking_status            VARCHAR(40) COMMENT 'Smoking status',
    bmi_value                 NUMBER(6,2) COMMENT 'Body mass index - the threshold input for bariatric criteria',
    bmi_recorded_date         DATE COMMENT 'Date the BMI was recorded',
    height_cm                 NUMBER(6,2) COMMENT 'Height in centimetres',
    weight_kg                 NUMBER(7,2) COMMENT 'Weight in kilograms',
    notes_text                VARCHAR(1000) COMMENT 'Free-text note',
    source_system             VARCHAR(40) NOT NULL COMMENT 'Originating system for this row (SYNTHEA, CMS_SYNPUF, FDA_NDC, CMS_ICD10, CMS_HCPCS, NPPES, SYNTHETIC, DERIVED)',
    ingested_at_utc           TIMESTAMP_NTZ NOT NULL COMMENT 'UTC timestamp the row was produced by the local pipeline',
    record_hash               VARCHAR(64) NOT NULL COMMENT 'SHA-256 over the row''s business columns. Stable across reruns with the same seed - this is what the determinism test compares.',
    CONSTRAINT pk_ext_patientmedicalhistory PRIMARY KEY (medical_history_id)
)
COMMENT = 'One row per longitudinal history item (a condition, medication, allergy, immunization or history entry) | Longitudinal patient history. The medication rows carry trial dates and PDC adherence, which is exactly what a step-therapy criterion needs; bmi_value supports the bariatric BMI thresholds. This is the primary evidence source for medical-necessity criteria evaluation.';
